function liveUrl(e,t={}){switch(e){case"meetdays":return`https://json.offtrackbetting.com/tracks/v2/${t.meetno}/meetdays.txt`;case"current_races":return"/api/current_races/v2";default:throw new Error(`liveUrl: unknown kind "${e}"`)}}function parseMeetdaysText(e){return e.split("\n").map(e=>e.trim()).filter(Boolean)}async function fetchMeetdaysLive(e){const t=await fetch(liveUrl("meetdays",{meetno:e}));if(!t.ok)throw new Error(`meetdays ${e}: HTTP ${t.status}`);return parseMeetdaysText(await t.text())}async function fetchCurrentRacesLive(){const e=await fetch(liveUrl("current_races"));if(!e.ok)throw new Error(`current_races: HTTP ${e.status}`);return e.json()}function normalizeTodayEntry(e){return e&&{race:e.currentRace,mtp:e.mtp,time:e.time,pd:e.programDate}}function isPendingMtp(e){return+e>=255}function formatYmd(e){const t=e.slice(0,4),r=e.slice(4,6),n=e.slice(6,8);return new Date(`${t}-${r}-${n}T12:00:00`).toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric"})}